async function main() {
  const allStandards = [
    ...ESKD, ...ESTD, ...ESPD, ...SPDS,
    ...WELDING, ...MATERIALS, ...TOLERANCES,
    ...SHIPBUILDING, ...OST, ...RD,
    ...REGISTER_MARITIME, ...REGISTER_RIVER,
    ...STO,
  ]
  console.log(`📚 Seeding ${allStandards.length} standards from real sources (docs.cntd.ru, rs-class.org, rr-reg.ru)...`)

  // Upsert всех стандартов + пунктов
  let inserted = 0, updated = 0
  for (const s of allStandards) {
    const existing = await db.standard.findUnique({ where: { code: s.code } })
    const data = {
      code: s.code,
      name: s.name,
      type: s.type,
      scope: s.scope,
      description: s.description ?? null,
      status: 'active',
      publishedAt: s.publishedAt ?? null,
      category: s.category,
      source: s.source ?? 'manual',
      sourceUrl: s.sourceUrl ?? null,
    }
    if (existing) {
      await db.standard.update({ where: { id: existing.id }, data })
      updated++
    } else {
      const created = await db.standard.create({ data })
      // Insert clauses if present
      if (s.clauses && s.clauses.length > 0) {
        for (const c of s.clauses) {
          await db.standardClause.create({
            data: {
              standardId: created.id,
              number: c.number,
              title: c.title,
              text: c.text,
              severity: c.severity ?? 'medium',
            },
          })
        }
      }
      inserted++
    }
  }
  console.log(`  ✓ ${inserted} new, ${updated} updated`)

  // Правила
  console.log(`📐 Seeding ${RULES.length} rules...`)
  for (const r of RULES) {
    const std = r.standardCode ? await db.standard.findUnique({ where: { code: r.standardCode } }) : null
    await db.rule.upsert({
      where: { code: r.code },
      update: {
        name: r.name,
        description: r.description,
        category: r.category,
        method: r.method,
        severity: r.severity,
        gostField: r.gostField,
        standardId: std?.id ?? null,
      },
      create: {
        code: r.code,
        name: r.name,
        description: r.description,
        category: r.category,
        method: r.method,
        severity: r.severity,
        gostField: r.gostField,
        enabled: true,
        standardId: std?.id ?? null,
      },
    })
  }
  console.log(`  ✓ ${RULES.length} rules`)

  // === Monetization: организация + API-ключ + подписка ===
  const orgCount = await db.organization.count()
  if (orgCount === 0) {
    const org = await db.organization.create({
      data: {
        name: 'АО "Судоверфь "Северо-Верфь"',
        slug: 'severo-verf',
        inn: '7800000000',
        contactEmail: 'nk@severo-verf.example',
        contactPhone: '+7 (812) 555-00-00',
        plan: 'pro',
        maxDocuments: 500,
        maxChecks: 2000,
        maxUsers: 15,
        status: 'active',
        trialEndsAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
      },
    })
    console.log(`🏢 Created organization: ${org.name}`)

    await db.user.create({
      data: {
        email: 'admin@severo-verf.example',
        name: 'Иванов Иван Иванович',
        role: 'admin',
        organizationId: org.id,
        status: 'active',
        lastLoginAt: new Date(),
      },
    })
    await db.user.create({
      data: {
        email: 'nk@severo-verf.example',
        name: 'Кузнецов Константин Константинович',
        role: 'normocontroller',
        organizationId: org.id,
        status: 'active',
      },
    })
    await db.user.create({
      data: {
        email: 'engineer@severo-verf.example',
        name: 'Петров Пётр Петрович',
        role: 'engineer',
        organizationId: org.id,
        status: 'active',
      },
    })
    console.log(`👥 Created 3 demo users (admin, normocontroller, engineer)`)

    // API-ключи
    const apiKey1Hash = 'demo_hash_' + Buffer.from('nk-pro-key-2025-abc123def456').toString('base64')
    await db.apiKey.create({
      data: {
        organizationId: org.id,
        name: 'Production API Key',
        keyPrefix: 'nk-pro-k',
        keyHash: apiKey1Hash,
        scopes: 'read,write',
        requestsLimit: 10000,
        periodStart: new Date(),
        status: 'active',
        expiresAt: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000),
      },
    })
    const apiKey2Hash = 'demo_hash_' + Buffer.from('nk-read-only-key-xyz789').toString('base64')
    await db.apiKey.create({
      data: {
        organizationId: org.id,
        name: 'CI/CD Read-Only Key',
        keyPrefix: 'nk-read-',
        keyHash: apiKey2Hash,
        scopes: 'read',
        requestsLimit: 5000,
        periodStart: new Date(),
        status: 'active',
      },
    })
    console.log(`🔑 Created 2 API keys`)

    // Подписка
    await db.subscription.create({
      data: {
        organizationId: org.id,
        plan: 'pro',
        status: 'active',
        amount: 49500,
        currency: 'RUB',
        interval: 'month',
        currentPeriodStart: new Date(),
        currentPeriodEnd: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
        paymentProvider: 'yookassa',
        externalId: 'sub_demo_001',
      },
    })
    console.log(`💳 Created subscription: Pro plan, 49 500 RUB/month`)

    // Несколько записей в аудит-логе
    const adminUser = await db.user.findFirst({ where: { role: 'admin' } })
    const nkUser = await db.user.findFirst({ where: { role: 'normocontroller' } })
    const actions = [
      { userId: adminUser?.id, action: 'organization.created', resourceType: 'organization', resourceId: org.id, details: JSON.stringify({ plan: 'pro' }) },
      { userId: adminUser?.id, action: 'apikey.created', resourceType: 'apikey', details: JSON.stringify({ name: 'Production API Key' }) },
      { userId: adminUser?.id, action: 'user.invited', resourceType: 'user', details: JSON.stringify({ email: 'nk@severo-verf.example', role: 'normocontroller' }) },
      { userId: nkUser?.id, action: 'rule.toggled', resourceType: 'rule', details: JSON.stringify({ code: 'R-MAT-005', enabled: true }) },
      { userId: nkUser?.id, action: 'standard.viewed', resourceType: 'standard', details: JSON.stringify({ code: 'ГОСТ 2.104-2006' }) },
    ]
    for (const a of actions) {
      await db.auditLog.create({ data: { organizationId: org.id, ...a, ipAddress: '192.168.1.100', userAgent: 'Mozilla/5.0' } })
    }
    console.log(`📜 Created ${actions.length} audit log entries`)

    // Привяжем существующие демо-документы к организации
    await db.document.updateMany({ where: { organizationId: null }, data: { organizationId: org.id } })
    console.log(`🔗 Linked existing documents to organization`)
  } else {
    console.log(`↪ Organizations already exist (${orgCount})`)
  }

  // Сводка
  const total = await db.standard.count()
  const rulesCount = await db.rule.count()
  const clausesCount = await db.standardClause.count()
  const usersCount = await db.user.count()
  const apiKeysCount = await db.apiKey.count()
  console.log(`\n📊 Final database state:`)
  console.log(`   Standards: ${total}`)
  console.log(`   Clauses: ${clausesCount}`)
  console.log(`   Rules: ${rulesCount}`)
  console.log(`   Organizations: ${await db.organization.count()}`)
  console.log(`   Users: ${usersCount}`)
  console.log(`   API keys: ${apiKeysCount}`)
  console.log(`   Audit logs: ${await db.auditLog.count()}`)
  console.log(`   Subscriptions: ${await db.subscription.count()}`)
  console.log('\n✅ Comprehensive seed complete!')
}

main()
  .catch((e) => {
    console.error('❌ Seed failed:', e)
    process.exit(1)
  })
  .finally(async () => {
    await db.$disconnect()
  })
